INSERT INTO `NB_AcademicCourse` (`course_ID`,`version_Key`,`definition_JSON`,`rule_JSON`,`properties_JSON`) VALUES
('AS1152','AS1152','{\"key\": \"AS1152\", \"level\": 1152, \"title\": \"Themes in U.S. History\", \"credits\": 4, \"courseCode\": \"AS1152\", \"labBearing\": false, \"description\": \"The course is an introduction to major issues in the history of the United States, from colonial times to the twentieth century. Topics may include: the origins of slavery and racism; industrialization and the growth of cities and suburbs; the growth of the American empire; movements for social change.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}',NULL),
('AS1282','AS1282','{\"key\": \"AS1282\", \"level\": 1282, \"title\": \"Introduction to African American Studies\", \"credits\": 4, \"courseCode\": \"AS1282\", \"labBearing\": false, \"description\": \"This is an introductory course in the themes and issues relevant to the inter-disciplinary field of African-American studies. Topics include: the origins and development of slavery and racism; African-American contributions to U.S. history; major African-American writers, artists, and thinkers; movements for political, racial, and economic equality.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"review-required\", \"reason\": \"prerequisite statement not supplied\", \"approvalAuthority\": \"authorized-academic-reviewer\"}',NULL),
('AS1512','AS1512','{\"key\": \"AS1512\", \"level\": 1512, \"title\": \"Introduction to Women’s, Gender, and Sexuality Studies\", \"credits\": 4, \"courseCode\": \"AS1512\", \"labBearing\": false, \"description\": \"Explores the development of sexed and gendered lives, from childhood through adolescence to maturity. Focuses on the family, school, sexuality, career options, and how these experiences and choices are affected by race, class, religion, ethnic origin, and gender. Readings include: fiction; autobiography; history; and social science. Offered every semester\", \"liberalArts\": true, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}','{\"level\": 1512, \"courseCode\": \"AS1512\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"d2507c5dfaca5998e35419ae2120b136a0467b2b38f772225d343a5ce3ef3755\", \"sectionAttributeEvidenceSHA256\": \"ee7eb380c15e5744017e44491f263598552324df494aac782ae119656b7639f1\"}'),
('AS2020','AS2020','{\"key\": \"AS2020\", \"level\": 2020, \"title\": \"New Media\", \"credits\": 4, \"courseCode\": \"AS2020\", \"labBearing\": false, \"description\": \"This introductory course explores new and emerging media through the lenses of history, technology, culture, and art. Students will engage with theory and analysis, alongside hands-on creative exercises using mobile media technology. Through readings, discussions, case studies, and experiments, we will examine new media aesthetics, storytelling strategies, and tools like virtual and augmented reality, video games, and apps. This course also delves into the impact of emerging media on journalism, documentary, activism, and its social and political implications.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}',NULL),
('AS2112','AS2112','{\"key\": \"AS2112\", \"level\": 2112, \"title\": \"American People l\", \"credits\": 4, \"courseCode\": \"AS2112\", \"labBearing\": false, \"description\": \"History of the American people to 1877, which emphasizes the diverse experiences and perspectives of women, people of color, working people, and other historically marginalized groups. Topics include the American Revolution and the Constitution, the origins and development of slavery, the development of Northern capitalism, territorial expansion and displacement of Native Americans, and the conflicts which led to the Civil War. Novels and films supplement more traditional texts.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2122','AS2122','{\"key\": \"AS2122\", \"level\": 2122, \"title\": \"American People II\", \"credits\": 4, \"courseCode\": \"AS2122\", \"labBearing\": false, \"description\": \"History of the American people, 1865 to present, which emphasizes the diverse experiences and perspectives of women, people of color, working people, and other historically marginalized groups. Topics include Reconstruction, the Industrial Revolution and the growth of the corporation, the creation of the working class, World Wars and American expansion, Progressivism, the Depression and the New Deal, the rise of industrial unionism, the Cold War, and the Civil Rights movement and new challenges emerging with the rise of global capitalism. Novels and films supplement more traditional texts.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2202','AS2202','{\"key\": \"AS2202\", \"level\": 2202, \"title\": \"Contemporary U.S. Society\", \"credits\": 4, \"courseCode\": \"AS2202\", \"labBearing\": false, \"description\": \"An introduction to social, economic and political stratification in the United States. Sources and consequences of inequality are explored through an examination of educational, political, and occupational structures.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"review-required\", \"reason\": \"prerequisite statement not supplied\", \"approvalAuthority\": \"authorized-academic-reviewer\"}',NULL),
('AS2252','AS2252','{\"key\": \"AS2252\", \"level\": 2252, \"title\": \"U.S. Social Movements\", \"credits\": 4, \"courseCode\": \"AS2252\", \"labBearing\": false, \"description\": \"This course explores the causal conditions, nature, and impact of progressive social movements in America. Varying sets of activist biographies and social movement histories related either by period or theme will be selected for study. Possible topics include the abolition, temperance, feminist, peace, labor, civil rights, reproductive rights, and environmental movements.\", \"liberalArts\": true, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}','{\"level\": 2252, \"courseCode\": \"AS2252\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"c993df3ba1c2495e00954281a918fdbf8e17a53a5bd04d4bcd4f67784da50df9\", \"sectionAttributeEvidenceSHA256\": \"7dbec7a84e0eb41bd01903c1550d37872c8c3c045086e0624b18dc60d81fcb4a\"}'),
('AS2262','AS2262','{\"key\": \"AS2262\", \"level\": 2262, \"title\": \"African American History l\", \"credits\": 4, \"courseCode\": \"AS2262\", \"labBearing\": false, \"description\": \"This course examines the experiences of African Americans in the development of America from the Trans-Atlantic slave trade through the Civil War. Topics include plantation slavery, politics, economics, cultural production, gender and intellectual pursuits. Emphasis on major movements and figures as well as ordinary individuals.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2263','AS2263','{\"key\": \"AS2263\", \"level\": 2263, \"title\": \"African American History II\", \"credits\": 4, \"courseCode\": \"AS2263\", \"labBearing\": false, \"description\": \"This course examines the experiences of African Americans in the development of America from 1865 through the twentieth century. Topics include Reconstruction, segregation, migrations, war, cultural production, entrepreneurship and the push for civil rights. Emphasis on social and cultural history across class and gender lines.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2300','AS2300','{\"key\": \"AS2300\", \"level\": 2300, \"title\": \"US Environmental History\", \"credits\": 4, \"courseCode\": \"AS2300\", \"labBearing\": false, \"description\": \"This course examines the history of Americans’ interactions with the physical environment of the current United States from the European colonial period to the present. Through assigned readings, class discussions, short films, short writing assignments, and speakers, we will consider 500 years of human occupation of North America and its environmental consequences. We will examine how natural environments have established parameters for human economic and social activity, as well as how human beings have interpreted and then reshaped their environmental surroundings in an effort to satisfy their perceived needs. In addition, we will study how different groups of Americans have interacted in their quest to manage, control and distribute the resources of the land, and the impact of “race” and gender on perceptions of our place in and relationship to the non-human environment.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2640','AS2640','{\"key\": \"AS2640\", \"level\": 2640, \"title\": \"U.S. Latina/o History\", \"credits\": 4, \"courseCode\": \"AS2640\", \"labBearing\": false, \"description\": \"This course will study the long history of Latina/os in the United States from the colonial era to the present, as well as explore important issues in Latina/o culture and politics. We will look in detail at the history of Mexican and Puerto Rican communities in the United States, and we will pay close attention to the impact of nationality, class, and gender in shaping Latina/o lives. This course will highlight the role of imperialism, racism, and nativism in structuring Latina/o opportunities in the United States, and will emphasize the social movements that Latinas/os have forged to resist such forces.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2700','AS2700','{\"key\": \"AS2700\", \"level\": 2700, \"title\": \"The Engaged Eye\", \"credits\": 4, \"courseCode\": \"AS2700\", \"labBearing\": false, \"description\": \"In this course students will be introduced to efforts by artists and art movements who use pencil, ink and press, paintbrush, camera, even bodies, along with other creative tools to comment on injustices and promote social change. The approach to the course will be interdisciplinary, with historical, art historical, biographical, social movement and visual culture lenses emphasized. Artists as diverse as John Sloan, Jacob Lawrence, Gordon Parks, Dorothea Lange, Charles White, Philip Guston, Louise Bourgeois, Ana Mendieta, Judy Chicago, Judy Baca, Kathy Vargas, Nancy Spero, and Juan Sanchez, will be studied. Students will explore how their art “worked” within their time period-how was it popularly understood, understood by critics, and how is it understood today? How were artists’ concerns and aesthetics connected to their time period? What are the continuities and ruptures in themes or aesthetics that unite artists and art movements? What kind of power does political art have, and for whom?\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS2750','AS2750','{\"key\": \"AS2750\", \"level\": 2750, \"title\": \"Food\", \"credits\": 4, \"courseCode\": \"AS2750\", \"labBearing\": false, \"description\": \"The production, consumption, and meanings of food are social, cultural and political. This course introduces students to prominent contemporary thinkers about food. Food is an interdisciplinary course drawing from history, environmental studies, documentary studies, sociology, anthropology, folklore, economics, critical race studies, and other fields. It will explore how food is understood, food and meal rituals, how food is produced, distributed, and consumed, with a focus on eating habits and the environment. The course will also introduce students to selected debates and initiatives around food: from diets such as vegetarianism, veganism, and locavorism; food and climate; the industrialization of food, the use of GMOs, food deserts, food insecurity, racial and gender injustice within the food justice movement, obesity and sizeism, and more.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"review-required\", \"reason\": \"prerequisite statement not supplied\", \"approvalAuthority\": \"authorized-academic-reviewer\"}',NULL),
('AS2802','AS2802','{\"key\": \"AS2802\", \"level\": 2802, \"title\": \"Multimedia Storytelling\", \"credits\": 4, \"courseCode\": \"AS2802\", \"labBearing\": false, \"description\": \"This hands-on course introduces students to nonfiction storytelling through text, photography, audio, video, and immersive media. Students learn to observe closely, engage with people and places, and communicate clearly to specific audiences-often through campus-based reporting. Through short projects such as photo stories, audio pieces, 360 video, and micro-profiles, students practice visual communication, interviewing, and narrative structure. Emphasizing creative expression, documentation, and peer critique, the course prepares students to craft compelling multimedia stories for contemporary platforms.\", \"liberalArts\": true, \"departmentId\": 10, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}','{\"level\": 2802, \"courseCode\": \"AS2802\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"2f3b7233a55cccdc5e9cd603c26e215e6625c94c07faf88861e764783ea64c9b\", \"sectionAttributeEvidenceSHA256\": \"32ee0a437da30326718ef3770bdda4e64d3c1a4d243a9d334499e5b24fce357e\"}'),
('AS2901','AS2901','{\"key\": \"AS2901\", \"level\": 2901, \"title\": \"Introduction to Video & TV\", \"credits\": 4, \"courseCode\": \"AS2901\", \"labBearing\": false, \"description\": \"In this introductory course (AS2901- formerly AS 3247), students will learn the basics of television and video production: camera operation, sound, lighting and editing for field and studio production. Through hands-on workshops, screenings, lectures and readings, students will explore the visual language of the moving image as well as the conventional and experimental approaches to non-fiction video, students will learn to use moving images and sound for artistic expression and as a tool for effective communication. Students will complete individual video projects shot in the field as well as a collaborative TV broadcast project produced in the television studio.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}','{\"level\": 2901, \"courseCode\": \"AS2901\", \"labBearing\": false, \"liberalArts\": false, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"a7304fec1fca463780fe07c039cdc62a85fe44a5080af9bcaeaf67fdd535af09\", \"sectionAttributeEvidenceSHA256\": \"35673f030d9a0cf6ecf3464417e9f691ec39c53e60413d7f012f85e97e3e781e\"}'),
('AS2902','AS2902','{\"key\": \"AS2902\", \"level\": 2902, \"title\": \"Introduction to Radio Production\", \"credits\": 4, \"courseCode\": \"AS2902\", \"labBearing\": false, \"description\": \"AS2902 Intro to Radio Production (formerly AS3820 Radio Production & Editing): Learn the basic techniques of radio production. Students will learn basic interviewing skills, studio production and mixing techniques, and how to manipulate digital audio recordings in post-production using industry editing software. Learn the basics of the three phases of production, including how to plan, script, create and edit radio content at the college radio station, OWWR, Old Westbury Web Radio.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"review-required\", \"reason\": \"prerequisite statement not supplied\", \"approvalAuthority\": \"authorized-academic-reviewer\"}',NULL),
('AS2910','AS2910','{\"key\": \"AS2910\", \"level\": 2910, \"title\": \"Podcasting and Audio Storytelling\", \"credits\": 4, \"courseCode\": \"AS2910\", \"labBearing\": false, \"description\": \"AS2910 Podcasting and Audio Storytelling (formerly AS3010): This media production course explores audio podcasting in many forms and includes lessons on recording, interviewing, script writing, narration, editing and sound mixing. The class will focus on developing engaging content and creative techniques for non-fiction storytelling through sound. Students will be encouraged to develop stories from their unique point-of-view, embedded in their communities or building on their academic research. We will explore voice in a number of ways: technical (on-air reporting voice), creative (directorial voice), and socio-political (amplifying historically underrepresented voices). Each week we will review professional podcasts which will serve as mentor texts for students as they produce their own projects. Student work will be reviewed at various stages of production, with regular peer and instructor critiques, allowing for an iterative creative process of output, feedback and revision.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": false, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS3000','AS3000','{\"key\": \"AS3000\", \"level\": 3000, \"title\": \"Feminisms, Bodies, Power\", \"credits\": 4, \"courseCode\": \"AS3000\", \"labBearing\": false, \"description\": \"Introduces contemporary issues in feminist theory and their historical origins for comprehensive study of feminist epistemologies and methods. Students will read both primary and secondary theoretical texts to study various feminisms which may include: liberalism; radical-liberalism; Marxist-socialist; psychoanalytic; care; sex and pleasure; multicultural, global and postcolonial; and, postmodern. This course is grounded in an intersectional perspective, introducing Black, Indigenous, women of color, queer and disability feminisms\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS3010','AS3010','{\"key\": \"AS3010\", \"level\": 3010, \"title\": \"Podcasting and Audio Storytelling\", \"credits\": 4, \"courseCode\": \"AS3010\", \"labBearing\": false, \"description\": \"This audio production course explores podcasting in many forms with a focus on creative techniques for non-fiction storytelling. Students will be encouraged to develop stories from their unique point-of-view, exploring topics important to their communities or building on their academic interests. Students will produce carefully crafted podcasts incorporating research, scripting, field and studio recording, interview, narration, editing and sound mixing.\", \"liberalArts\": true, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}','{\"level\": 3010, \"courseCode\": \"AS3010\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"fc67346d9c6890457657cdf3ca2a921beccd007de6452c72d3c0bb7c252c43f8\", \"sectionAttributeEvidenceSHA256\": \"a21bfce292009ffa78819e9423d6fb14421488a6da2b285a9839949361b8a828\"}'),
('AS3100','AS3100','{\"key\": \"AS3100\", \"level\": 3100, \"title\": \"American Studies Seminar\", \"credits\": 4, \"courseCode\": \"AS3100\", \"labBearing\": false, \"description\": \"This course is designed for American Studies majors, or those contemplating an American Studies major. The course will build appreciation of American Studies as interdisciplinary study. In preparation for the 5000-level capping courses, this course builds students’ analytic, research and writing skills. The American Studies Seminar focuses on a particular issue or theme, which will be announced each semester.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"or\", \"rules\": [{\"key\": \"ECII\", \"type\": \"proficiency\"}, {\"type\": \"approval\", \"authority\": \"course-instructor\"}]}',NULL),
('AS3215','AS3215','{\"key\": \"AS3215\", \"level\": 3215, \"title\": \"Crime, Protest, and Policing\", \"credits\": 4, \"courseCode\": \"AS3215\", \"labBearing\": false, \"description\": \"This course will explore the reality and discourse around crime, protest, and policing from the late nineteenth century to the present. We will discuss both the actions and explanations of people who broke the law, the consequences they faced, and the shifting cultural narratives that have formed around the idea of ‘criminals.’\", \"liberalArts\": true, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}','{\"level\": 3215, \"courseCode\": \"AS3215\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"e5ea7935a9e7cf4833036124134e46831950c76c6b2ff6c9fb591e216c6d799b\", \"sectionAttributeEvidenceSHA256\": \"185350867a1737709001d154ac5180bd5995fd4c57ac51c9315865faa470d472\"}'),
('AS3222','AS3222','{\"key\": \"AS3222\", \"level\": 3222, \"title\": \"Urban History\", \"credits\": 4, \"courseCode\": \"AS3222\", \"labBearing\": false, \"description\": \"This course investigates urban history in the United States with a focus on the 20th century and on the role of race and ethnicity in shaping urban America. Using an array of scholarly texts, media, and primary source documents, this course will trace the social, economic, and cultural history of U.S. cities and the growth of their suburbs. Topics will include: the formation of early-twentieth century immigrant/ethnic communities and the advent of neighborhood segregation; the Great Migrations of African Americans to the urban North; white flight, suburbanization, and urban economic decline after WW II; urban “crisis” and radical anti-racism in the 1960s and 70s; gentrification, mass incarceration, and the rise of “Global Cities” toward the end of the century.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}',NULL),
('AS3247','AS3247','{\"key\": \"AS3247\", \"level\": 3247, \"title\": \"Introduction to Video and TV\", \"credits\": 4, \"courseCode\": \"AS3247\", \"labBearing\": false, \"description\": \"In this introductory course, students will learn the basics of television and video production: camera operation, sound, lighting and editing for field and studio production. Through hands-on workshops, screenings, lectures and readings, students will explore the visual language of the moving image as well as the conventional and experimental approaches to non-fiction video, students will learn to use moving images and sound for artistic expression and as a tool for effective communication. Students will complete individual video projects shot in the field as well as a collaborative TV broadcast project produced in the television studio.\", \"liberalArts\": true, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"no-course-prerequisites\", \"basis\": \"No prerequisite or corequisite is listed in the supplied complete catalog entry.\"}','{\"level\": 3247, \"courseCode\": \"AS3247\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"48d8b2fbaec54e4bf29122fa3170639876dace6afba836f21b0d1fce4ed5212c\", \"sectionAttributeEvidenceSHA256\": \"a53646363f635fd2a7bd0865bef495fccfa57457f6ec9a69336878a142fe794a\"}'),
('AS3250','AS3250','{\"key\": \"AS3250\", \"level\": 3250, \"title\": \"Scriptwriting for Television\", \"credits\": 4, \"courseCode\": \"AS3250\", \"labBearing\": false, \"description\": \"Students study the world of television writing through thorough analyzing popular shows and learning the formula and format for writing a spec (sample) script for a current television show. Students are taught the language of scripts and scriptwriting, how to come up with an original idea, how to develop a good story, how to write good characters, how to write an outline and develop and write scenes for their script. The course is focused on half-hour comedies and dramedies featured on the major broadcast networks (ABC, CBS, NBC), cable television (HBO, SHOWTIME STARZ) and streaming networks (NETFLIX, HULU, APPLE TV+).\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"EMS\", \"type\": \"proficiency\"}',NULL),
('AS3270','AS3270','{\"key\": \"AS3270\", \"level\": 3270, \"title\": \"Africa in the Americas\", \"credits\": 4, \"courseCode\": \"AS3270\", \"labBearing\": false, \"description\": \"This course will explore the history of these scattered populations of Africa, their dispersal to the various regions of the world, especially the Western hemisphere, the circumstances and institutions which shaped the evolution of these diaspora communities, and the continuing physical and emotional ties to Africa and Africans. The dispersal of black people from their homes in the continent of Africa to the diverse geographical sites all around the world is one of the more momentous, historical and sociological events in the trajectory of world history.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}',NULL),
('AS3310','AS3310','{\"key\": \"AS3310\", \"level\": 3310, \"title\": \"From Citizen to Consumer\", \"credits\": 4, \"courseCode\": \"AS3310\", \"labBearing\": false, \"description\": \"American society has transformed since its founding from a commercial outpost on the edge of the Atlantic to a complex industrial democracy. This course examines that transformation in light of its impact on notions of democracy, the work ethic and good citizenship and the shift toward a post-industrial empire of mass consumption and leisure. Using historical documents of political theorists, advocates and critics of consumerism, as well as social movements for consumer rights, alongside contemporary materials such as advertising campaigns and policy debates, students will explore how this change has altered our very notions of identity, democracy and citizenship.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}',NULL),
('AS3412','AS3412','{\"key\": \"AS3412\", \"level\": 3412, \"title\": \"African-American Women’s History\", \"credits\": 4, \"courseCode\": \"AS3412\", \"labBearing\": false, \"description\": \"This course focuses on the distinct experiences of African-American women in the 19th and 20th centuries. The course includes the experiences of women in slavery, social movements, abolition, anti-lynching, suffrage, civil rights, and Black Power as well as the writings and lives of the major figures.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}',NULL),
('AS3432','AS3432','{\"key\": \"AS3432\", \"level\": 3432, \"title\": \"Women: Cultural Issues\", \"credits\": 4, \"courseCode\": \"AS3432\", \"labBearing\": false, \"description\": \"An interdisciplinary course that looks at the lives of women across the world. Readings and materials focus on the variety of circumstances in which women live, the factors that directly influence their situation, the interaction between cultural constraints and existential possibilities, and women’s efforts to change and improve their own and others’ lives. In this course students also examine how women in multiple contexts utilize mass culture and develop new cultural forms to advance their interests.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}',NULL),
('AS3462','AS3462','{\"key\": \"AS3462\", \"level\": 3462, \"title\": \"History of Women in the U.S.\", \"credits\": 4, \"courseCode\": \"AS3462\", \"labBearing\": false, \"description\": \"This course surveys women’s experience from 1620 to the present. The course analyzes women’s connection to key aspects of American history such as the American Revolution, slavery and the 20th century development of the welfare state. This course posits women as agents of change in American history, but the course also examines how the study of women over time raises questions about traditional chronologies of American history. Students will be introduced to well-known and little known women and their individual and collective attempts to reshape American society through examination of diaries, autobiographies, fiction, government hearings and film.\", \"liberalArts\": true, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECII\", \"type\": \"proficiency\"}','{\"level\": 3462, \"courseCode\": \"AS3462\", \"labBearing\": false, \"liberalArts\": true, \"categoryBasis\": \"Reviewed explicit program lists and course descriptions; positive approved uses only.\", \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": [], \"liberalArtsBasis\": \"Consistent public section LA attribute; absence contributes zero LA credits.\", \"upperDivisionBasis\": \"College-wide source defines 3000, 4000 and 5000 levels as upper division.\", \"sourceMetadataSHA256\": \"b2d6a8d3f977f8ee5cbf3823ed064257113055667c869f6713f3e8dd53bce410\", \"sectionAttributeEvidenceSHA256\": \"73076ca05825130429acb44cf280f531755455f7091cb0ad7e78dc66288d8853\"}'),
('AS3722','AS3722','{\"key\": \"AS3722\", \"level\": 3722, \"title\": \"History of Mass Media\", \"credits\": 4, \"courseCode\": \"AS3722\", \"labBearing\": false, \"description\": \"Covers the historical development and social and political importance of the mass media in the U.S. It concentrates on the growth of consumerism and advertising , as well as on radio, film, and the growth of TV. It also examines popular forms of expression, such as music and popular art, as they relate to mass culture.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"course\", \"courseCode\": \"EL1000\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}',NULL),
('AS3750','AS3750','{\"key\": \"AS3750\", \"level\": 3750, \"title\": \"AI & Society\", \"credits\": 4, \"courseCode\": \"AS3750\", \"labBearing\": false, \"description\": \"Artificial Intelligence technologies are being integrated into our lives. What do you need to know about Artificial Intelligence? Will it disrupt everything? Will you survive? Could you even thrive in the wake of this A.I. tsunami? A.I. & Society begins with the fundamentals of A.I. literacy by explaining foundational concepts. Understanding these fundamentals, we will develop a complex analysis of the positive and negative effects of this technological revolution. What predictions can we make for our A.I. future? What are the dangers of an accelerated adoption of untested technologies? Can A.I. be aligned with human values? Will we prosper as augmented humans empowered by artificial general intelligence? How will A.I. impact our personal, professional and political lives?\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"course\", \"courseCode\": \"EL1000\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}',NULL),
('AS3800','AS3800','{\"key\": \"AS3800\", \"level\": 3800, \"title\": \"Writing for Media\", \"credits\": 4, \"courseCode\": \"AS3800\", \"labBearing\": false, \"description\": \"The course combines instruction in the craft of journalism and teaches students to write accurately and clearly and to meet deadlines. The basics of good reporting whether for print, broadcast, or internet journalism are stressed, including how to gather and verify information, where to look for stories, how to interview, how to use sources, and how to report in a fair and balanced manner. Students will write about and cover a variety of news events and issues.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"EMS\", \"type\": \"proficiency\"}',NULL),
('AS3820','AS3820','{\"key\": \"AS3820\", \"level\": 3820, \"title\": \"Radio Production and Editing\", \"credits\": 4, \"courseCode\": \"AS3820\", \"labBearing\": false, \"description\": \"Learn the basic techniques of radio production. Students will learn basic interviewing skills, studio production and mixing techniques, and how to manipulate digital audio recordings in post-production using industry editing software. Learn the basics of the three phases of production, including how to plan, script, create and edit radio content at the college radio station, OWWR, Old Westbury Web Radio.\", \"liberalArts\": false, \"departmentId\": 10, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"key\": \"ECI\", \"type\": \"proficiency\"}',NULL),
('AS4000','AS4000','{\"key\": \"AS4000\", \"level\": 4000, \"title\": \"Civil Rights and Congress I\", \"credits\": 4, \"courseCode\": \"AS4000\", \"labBearing\": false, \"description\": \"This two-part history course is based on the constitutional foundations of the civil rights laws passed by Congress during the modern rights movement. Part I highlights the first phase of the 20th century legislative struggle, beginning with the Niagara Movement through the struggles for anti-lynching, anti-poll tax, the Powell Amendment non- discrimination principle in federally funded programs, a permanent Fair Employment Practice, and other civil rights laws that led to passage in 1957 of the first civil rights act since Reconstruction. The course is structured with selections from published sources and primary documents from the collection of the NAACP Washington Bureau and its administrative files.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"or\", \"rules\": [{\"type\": \"and\", \"rules\": [{\"type\": \"or\", \"rules\": [{\"type\": \"course\", \"courseCode\": \"AS2112\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2122\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2252\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2262\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2263\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2300\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2640\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3215\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3222\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3270\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3462\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}]}, {\"key\": \"EMS\", \"type\": \"proficiency\"}]}, {\"type\": \"approval\", \"authority\": \"course-instructor\"}]}',NULL),
('AS4001','AS4001','{\"key\": \"AS4001\", \"level\": 4001, \"title\": \"Civil Rights and Congress II\", \"credits\": 4, \"courseCode\": \"AS4001\", \"labBearing\": false, \"description\": \"This two-part history course is based on the constitutional foundations of the civil rights laws passed by Congress during the modern rights movement. Part II is the second phase of the 20th century legislative struggle, beginning with the sit-in demonstrations and Freedom Rides in the South, and other aspects of nonviolent protests that brought worldwide attention to the wanton denial of civil rights for African American, which intensified pressure on Congress to pass civil rights laws and on the Executive Branch to adopt constructive policies to protect those constitutional rights.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"or\", \"rules\": [{\"type\": \"and\", \"rules\": [{\"type\": \"or\", \"rules\": [{\"type\": \"course\", \"courseCode\": \"AS2112\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2122\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2252\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2262\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2263\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2300\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2640\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3215\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3222\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3270\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3462\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}]}, {\"key\": \"EMS\", \"type\": \"proficiency\"}]}, {\"type\": \"approval\", \"authority\": \"course-instructor\"}]}',NULL),
('AS4170','AS4170','{\"key\": \"AS4170\", \"level\": 4170, \"title\": \"Special Topics in American Studies\", \"credits\": 4, \"courseCode\": \"AS4170\", \"labBearing\": false, \"description\": \"This course addresses a special topic in the history, society and/or culture of the U.S. The specific topic will be announced by the Department when offered. The course may be repeated for credit up to two times if course topic changes.\", \"liberalArts\": false, \"departmentId\": 7, \"upperDivision\": true, \"catalogVersion\": \"2026-2027\", \"classifications\": []}','{\"type\": \"or\", \"rules\": [{\"type\": \"and\", \"rules\": [{\"type\": \"or\", \"rules\": [{\"type\": \"course\", \"courseCode\": \"AS2112\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2122\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2252\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2262\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2263\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2300\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS2640\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3215\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3222\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3270\", \"minimumGrade\": null, \"minimumGradeStatus\": \"not-specified-in-source\"}, {\"type\": \"course\", \"courseCode\": \"AS3462\